<?php
class View {
 static function thumbnail(string $path):string{$thumb=preg_replace('/\.webp$/','-thumb.webp',$path);return base(str_starts_with($path,'uploads/')&&is_file(ROOT.'/public/'.$thumb)?$thumb:$path);}
 static function icon(string $name):string{$paths=['search'=>'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>','cart'=>'<path d="M3 3h2l3 13h11l3-9H6"/><circle cx="9" cy="21" r="1"/><circle cx="19" cy="21" r="1"/>','heart'=>'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>','user'=>'<circle cx="12" cy="7" r="4"/><path d="M3 22v-3a9 9 0 0 1 18 0v3Z"/>','menu'=>'<path d="M3 6h18M3 12h18M3 18h18"/>','arrow'=>'<path d="M3 12h18m-7-7 7 7-7 7"/>','box'=>'<path d="m12 3 9 5v10l-9 5-9-5V8Zm0 10v10M3 8l9 5 9-5M7 5l10 6"/>','check'=>'<path d="m4 12 5 5L20 6"/>','close'=>'<path d="m5 5 14 14M5 19 19 5"/>'];return '<svg aria-hidden="true" class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'.($paths[$name]??$paths['box']).'</svg>';}
 static function card(array $p):void{?><article class="product-card"><div class="product-visual"><a href="<?=e(url('product',['slug'=>$p['slug']]))?>"><img loading="lazy" src="<?=e(self::thumbnail($p['image']?:'assets/placeholder.svg'))?>" alt="<?=e($p['name'])?>"></a><?php if($p['deal']):?><span class="badge">Sale</span><?php elseif($p['new_arrival']):?><span class="badge pale">New arrival</span><?php endif?><?php if(enabled('wishlist')):?><button class="wish icon-button" data-wish="<?=$p['id']?>" aria-label="Save <?=e($p['name'])?> to wishlist"><?=self::icon('heart')?></button><?php endif?></div><div class="product-copy"><small><?=e($p['category'])?></small><a class="product-name" href="<?=e(url('product',['slug'=>$p['slug']]))?>"><?=e($p['name'])?></a><?php if(enabled('reviews')&&$p['rating']):?><span class="rating">★ <?=e(number_format((float)$p['rating'],1))?> approved reviews</span><?php else:?><span class="muted tiny">Original sample product</span><?php endif?><div class="price-row"><b><?=money($p['price'])?></b><a class="round-link" href="<?=e(url('product',['slug'=>$p['slug']]))?>" aria-label="View <?=e($p['name'])?>"><?=self::icon('arrow')?></a></div></div></article><?php }
 static function credit():void{?><div class="credit">Software Development by <a href="https://www.energeticedge.lk/" target="_blank" rel="noopener noreferrer">Energetic Edge (Pvt) Ltd</a></div><?php }
 static function attributeFilter(array $a,string $value=''):void{$options=all('SELECT label FROM attribute_options WHERE attribute_id=?',[$a['id']]);?><label><?=e($a['name'])?><?php if($options||$a['type']==='boolean'):?><select name="attr[<?=$a['id']?>]"><option value="">Any</option><?php if($a['type']==='boolean')$options=[['label'=>'0'],['label'=>'1']];foreach($options as $o):?><option value="<?=e($o['label'])?>" <?=$value===$o['label']?'selected':''?>><?=e($a['type']==='boolean'?($o['label']==='1'?'Yes':'No'):$o['label'])?></option><?php endforeach?></select><?php else:?><input name="attr[<?=$a['id']?>]" type="<?=e($a['type']==='date'?'date':($a['type']==='number'?'number':'text'))?>" step="any" value="<?=e($value)?>"><?php endif?></label><?php }
 static function field(string $name,string $label,string $type='text',mixed $value='',bool $required=false):void{?><label><?=e($label)?><?=$required?' *':''?><?php if($type==='textarea'):?><textarea name="<?=e($name)?>" <?=$required?'required':''?>><?=e($value)?></textarea><?php else:?><input type="<?=e($type)?>" name="<?=e($name)?>" value="<?=e($value)?>" <?=$required?'required':''?> <?php if($type==='password'):?>minlength="12" autocomplete="new-password"<?php endif?>><?php endif?><small data-error="<?=e($name)?>"></small></label><?php }
}
